# SYNTHETIC learning fixture (not production code).
class ReportService:
    def _daily(self):
        return "daily report"

    def _weekly(self):
        return "weekly report"

    def run(self, action):
        handlers = {"daily": self._daily, "weekly": self._weekly}
        handler = handlers.get(action)
        if handler is None:
            raise ValueError("unknown action")
        return handler()
